mapper.select:
SELECT ai.*
FROM approval_instance ai
INNER JOIN approval_flow_version afv ON afv.id = ai.flow_version_id
WHERE ai.id = #{instanceId}
  AND afv.organization_id = #{organizationId}

SELECT ai.resource_id AS resourceId, COALESCE(ai.resource_name, '资源不存在') AS resourceName, UPPER(ai.type) AS resourceType, u.name AS applicant, ai.submit_time AS submitTime, ai.execute_time, ai.approval_status AS dataResult, ai.id AS approvalInstanceId, afv.flow_id AS approvalFlowId, afv.id AS approvalFlowVersionId, m.id AS commentMentionId, c.id AS commentId, m.create_time AS mentionTime
LEFT JOIN sys_user u ON u.id = ai.submitter_id WHERE m.user_id = #{userId} AND c.organization_id = #{organizationId} AND afv.organization_id = #{organizationId}
AND ai.type = #{resourceType}
AND ai.resource_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY m.create_time DESC, m.id DESC

SELECT ai.*

WHERE m.id = #{mentionId}
  AND m.user_id = #{userId}
  AND c.organization_id = #{organizationId}
  AND afv.organization_id = #{organizationId}

